    for(const field of root.querySelectorAll('[data-study-field]'))field.disabled=Boolean(busy);
    for(const field of root.querySelectorAll('[data-study-root]'))field.disabled=Boolean(busy)||field.dataset.studyUnavailable==='true';
    for(const field of root.querySelectorAll('[data-study-action="open-spatial"],[data-study-action="open-monitoring"],[data-study-action="open-sampling"],[data-study-action="open-paired"],[data-study-action="open-report-comparison"],[data-study-action="open-management-design"]'))field.disabled=Boolean(busy);
  }

  function terrainControl(row){
    if(!row?.kind?.startsWith('terrain-conditioning-')||row.state==='unreadable'||
       !/^[0-9a-f]{64}$/.test(row?.id||'')||typeof host.openDesk!=='function')return '';
    const response=['terrain-conditioning-responses','terrain-conditioning-report-sources'].includes(row.kind);
    const id=response?(row.response_id||(row.kind==='terrain-conditioning-responses'?row.id:null)):
      (row.case_id||(row.kind==='terrain-conditioning-cases'?row.id:null));
    if(!/^[0-9a-f]{64}$/.test(id||''))return '';
    return button('open-terrain',response?'Open original terrain response':'Open original terrain case',
      'data-study-kind="'+escapeHTML(row.kind)+'" data-study-id="'+escapeHTML(row.id)+'"');
  }
  async function openTerrain(kind,id){
    const row=[...visiblePage().items,...(plan?.nodes||[])].find(value=>
      value.kind===kind&&value.id===id&&value.state!=='unreadable');
    if(!row||!terrainControl(row))throw Error('Refresh the original saved terrain study.');
    const origin=workspaceNow(),response=['terrain-conditioning-responses','terrain-conditioning-report-sources'].includes(kind);
    const target=response?(row.response_id||id):(row.case_id||id);
    try{return await host.openDesk('terrain-conditioning',response?'openSavedResponse':'openSavedCase',{
      workspace_key:origin,[response?'response_id':'case_id']:target,
      isCurrent:()=>workspaceNow()===origin
    });}catch(error){if(workspaceNow()!==origin)return null;throw error;}
  }

  function controlOutcomeControl(row){
    if(row?.kind!=='multivariate-control-outcomes'||row.state==='unreadable'||
       !/^[0-9a-f]{64}$/.test(row?.id||'')||typeof host.openDesk!=='function')return '';
