  process.exit(0);
}
const output = resolve(args.output || 'scientific-report-browser');
const journal = {
  schema: 'upstate.scientific-report-browser/v1', started_at: new Date().toISOString(),
  state: 'running', steps: [], downloads: [], screenshots: [], browser_errors: [],
