"""Durable project primitives; no provider credentials or global runtime state."""
from __future__ import annotations
import contextlib
import datetime as dt
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shutil
import stat
import tempfile
from .verified_files import source_identity, verified_operation

SCHEMA = "upstate.scientific-workbench/v1"
INVEST_VERSION = "3.20.0"
INVEST_SOURCE = {
    "repository": "https://github.com/natcap/invest",
    "ref": "3.20.0",
    "ndr_blob": "f518b2867d4a327675fcb1c9b4ba56f29b12188d",
    "sdr_blob": "0cac27add172011df367ff8026427dbbdbcda5b2",
}
ROLES = ("DEM", "NLCD", "PRECIPITATION", "R_FACTOR", "K_FACTOR")
MODELS = ("ndr", "sdr")
MODEL_ROLES = {
    "ndr": ("DEM", "NLCD", "PRECIPITATION"),
    "sdr": ("DEM", "NLCD", "R_FACTOR", "K_FACTOR"),
}
MODEL_OUTPUTS = {
    "nitrogen_export": ("ndr", "n_total_export"),
    "phosphorus_export": ("ndr", "p_surface_export"),
    "sediment_export": ("sdr", "sed_export"),
}
SOURCE_IDS = ROLES + ("PROTECTED_LANDS", "PARCEL", "NHD", "NWI", "LS_FACTOR")
MAP_IDS = ("future_sediment_loss", "future_nutrient_runoff",
           "critical_drinking_water", "high_quality_waters",
           "current_nutrient_export", "current_sediment_export",
           "combined_pollutant_export")

def selected_models(value=None):
    """Return selected native models in their stable execution order.

    An omitted selection preserves the original combined NDR/SDR behavior.
    The explicit selection is carried by a profile, grid or run's models field.
    """
    values = value.get("models", MODELS) if isinstance(value, dict) else value
    if values is None and value is None:
        values = MODELS
    if not isinstance(values, (list, tuple)) or not values:
        raise ValueError("Select a nonempty list of native models: ndr, sdr")
    if any(not isinstance(name, str) for name in values):
        raise ValueError("Native model names must be ndr or sdr")
    names = [name.strip().lower() for name in values]
    if len(names) != len(set(names)) or set(names) - set(MODELS):
        raise ValueError("Select each native model once from ndr, sdr")
    return [name for name in MODELS if name in names]

def required_roles(value=None):
    """Physical inputs required by the selected native models."""
    models = selected_models(value)
    return tuple(role for role in ROLES
                 if any(role in MODEL_ROLES[model] for model in models))

def output_models(value=None):
    """Map actual selected export names to native model/registry identifiers."""
    models = selected_models(value)
    return {name: pair for name, pair in MODEL_OUTPUTS.items() if pair[0] in models}

def now():
    return dt.datetime.now(dt.timezone.utc).isoformat()

def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")

def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()

def file_digest(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1024 * 1024), b""):
            h.update(b)
    return h.hexdigest()

def atomic_bytes(path, data, *, immutable=False):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if immutable and path.exists():
        if path.read_bytes() != data:
            raise ValueError("Immutable project item differs: " + str(path))
        return
    pending = None
    try:
        with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".write-", delete=False) as f:
            pending = Path(f.name)
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        if immutable:
            try:
                os.link(pending, path)
            except FileExistsError:
                if path.read_bytes() != data:
                    raise ValueError("Concurrent immutable item differs: " + str(path))
            pending.unlink()
            pending = None
        else:
            os.replace(pending, path)
            pending = None
        fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    finally:
        if pending is not None:
            pending.unlink(missing_ok=True)

def atomic_json(path, value, *, immutable=False):
    atomic_bytes(path, canonical(value) + b"\n", immutable=immutable)

def read_json(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))

def identifier(value):
    if not isinstance(value, str) or not re.fullmatch(r"[0-9a-f]{64}", value):
        raise ValueError("Select an existing complete project item ID")
    return value

def relative_file(root, value):
    root = Path(root).resolve()
    selected = Path(value)
    if selected.is_absolute() or not selected.parts or ".." in selected.parts:
        raise ValueError("Use a relative file within the selected project")
    p = (root / selected).resolve(strict=True)
    if not p.is_relative_to(root) or not p.is_file():
        raise ValueError("Project member is not a retained regular file")
    return p

def finite(value, name, *, minimum=None, positive=False):
    if isinstance(value, bool):
        raise ValueError(name + " must be numeric")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(name + " must be finite")
    if minimum is not None and result < minimum or positive and result <= 0:
        raise ValueError(name + " is outside its permitted range")
    return result

@contextlib.contextmanager
def held(path, *, blocking=True):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | (0 if blocking else fcntl.LOCK_NB))
        yield
    finally:
        os.close(fd)

def _file_state(value):
    return (value.st_dev, value.st_ino, value.st_size,
            value.st_mtime_ns, value.st_ctime_ns)

def _sync_directory(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)

def _stream_identity(stream, label, *, expected_state=None, output=None):
    before = os.fstat(stream.fileno())
    if not stat.S_ISREG(before.st_mode):
        raise ValueError(label + " is not a regular file")
    state = _file_state(before)
    if expected_state is not None and state != expected_state:
        raise ValueError(label + " changed during intake")
    checksum, size = hashlib.sha256(), 0
    for block in iter(lambda: stream.read(1024 * 1024), b""):
        checksum.update(block)
        if output is not None:
            output.write(block)
        size += len(block)
    if _file_state(os.fstat(stream.fileno())) != state or size != before.st_size:
        raise ValueError(label + " changed during intake")
    return checksum.hexdigest(), size, state

def _retained_object_matches(path, checksum, size, *, verified_state=None):
    try:
        descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    except FileNotFoundError:
        return False
    with os.fdopen(descriptor, "rb") as stream:
        opened = os.fstat(stream.fileno())
        if not stat.S_ISREG(opened.st_mode):
            raise ValueError("Retained original object is not a regular file")
        state = _file_state(opened)
        try:
            # Reuse only an identity recorded by this operation, never a bare
            # caller-provided stat tuple. Keep verified_state for API continuity.
            actual, count, state = source_identity(
                stream, path, "Retained original object")
        except (ValueError, FileNotFoundError):
            # A concurrent completed publication or view hard link can change
            # ctime. Recheck under the digest lock before any copy or repair.
            return False
        try:
            current = path.lstat()
        except FileNotFoundError:
            return False
        if _file_state(current) != state or not stat.S_ISREG(current.st_mode):
            return False
        if actual != checksum or count != size:
            return False
        # Complete publication durability even after an interrupted prior intake.
        os.fsync(stream.fileno())
        return True

@verified_operation
def retain_file(project, source, expected_sha256=None):
    """Retain one independent input copy, reusing banked bytes and interrupted intake."""
    source = Path(source).resolve(strict=True)
    if not source.is_file():
        raise ValueError("Source is not a regular file")
    directory = Path(project) / "objects"
    directory.mkdir(parents=True, exist_ok=True)
    expected = identifier(expected_sha256) if expected_sha256 is not None else None
    pending = None
    with source.open("rb") as src:
        if expected is None:
            checksum, size, source_state = source_identity(src, source, "Original input")
            source_verified = True
        else:
            opened = os.fstat(src.fileno())
            if not stat.S_ISREG(opened.st_mode):
                raise ValueError("Original input is not a regular file")
            checksum, size, source_state = expected, opened.st_size, _file_state(opened)
            source_verified = False
        destination = directory / checksum

        def matches():
            return _retained_object_matches(
                destination, checksum, size,
                verified_state=source_state if source_verified else None)

        def reused():
            nonlocal source_verified
            if not source_verified:
                src.seek(0)
                actual, count, _ = source_identity(
                    src, source, "Original input", expected_state=source_state)
                if actual != checksum or count != size:
                    raise ValueError("Original source hash differs: " + source.name)
                source_verified = True
            if _file_state(os.fstat(src.fileno())) != source_state:
                raise ValueError("Original input changed during intake")
            _sync_directory(directory)
            _sync_directory(directory.parent)
            return {"sha256": checksum, "bytes": size,
                    "object": "objects/" + checksum, "filename": source.name}

        # An existing verified object reopens without allocating a lock or a
        # temporary file, including on a full receiving volume.
        if matches():
            return reused()
        with held(directory / (".intake-" + checksum + ".lock")):
            if _file_state(os.fstat(src.fileno())) != source_state:
                raise ValueError("Original input changed during intake")
            if matches():
                return reused()
            try:
                src.seek(0)
                candidate = directory / (".intake-" + checksum + ".partial")
                if candidate.resolve() == source:
                    raise ValueError("Select an original input outside its unfinished intake path")
                # Every retry owns the same digest lock and pending name.
                # Unlink an old alias before creating an independent inode:
                # truncating a prior installed hard link would damage its object.
                candidate.unlink(missing_ok=True)
                descriptor = os.open(candidate, os.O_WRONLY | os.O_CREAT |
                                     os.O_EXCL | os.O_NOFOLLOW, 0o600)
                pending = candidate
                with os.fdopen(descriptor, "wb") as out:
                    copied, copied_size, _ = source_identity(
                        src, source, "Original input", expected_state=source_state, output=out)
                    if copied != checksum or copied_size != size:
                        raise ValueError("Original source hash differs: " + source.name)
                    out.flush()
                    os.fsync(out.fileno())
                if _file_state(os.fstat(src.fileno())) != source_state:
                    raise ValueError("Original input changed during intake")
                try:
                    os.link(pending, destination)
                except FileExistsError:
                    # Preserve a complete concurrent publication or atomically
                    # repair a damaged regular object with this verified copy.
                    if not _retained_object_matches(destination, checksum, size):
                        os.replace(pending, destination)
                        pending = None
                _sync_directory(directory)
                _sync_directory(directory.parent)
            finally:
                if pending is not None:
                    pending.unlink(missing_ok=True)
                    _sync_directory(directory)
    return {"sha256": checksum, "bytes": size, "object": "objects/" + checksum,
            "filename": source.name}

def verify_file(root, item):
    from .verified_files import verify_path
    return verify_path(relative_file(root, item["path"]), item)

def describe_file(root, path, **metadata):
    path = Path(path).resolve(strict=True)
    root = Path(root).resolve()
    if not path.is_relative_to(root):
        raise ValueError("Output is outside the current run")
    return {**metadata, "path": path.relative_to(root).as_posix(),
            "bytes": path.stat().st_size, "sha256": file_digest(path)}

files.model/native_versions.py:
"""Executed native-model versions, preserving retained per-stage provenance."""
from __future__ import annotations

from copy import deepcopy
from urllib.parse import quote
from .model_selection import MODEL_OUTPUTS, run_models

POLICY = "completed_stage_runtime_else_observed_run_else_labeled_requested_legacy"


def _text(value):
    return value.strip() if isinstance(value, str) and value.strip() else None


def native_version(run):
    """Retain the historical run-level declaration and last observed runtime."""
    requested = _text(run.get("selection", {}).get("invest_version"))
    observed = _text((run.get("runtime") or {}).get("version"))
    return {"requested": requested, "observed": observed,
            "comparison_version": observed or requested,
            "basis": "observed_runtime" if observed else "requested_legacy" if requested else "unavailable",
            "differs_from_requested": bool(observed and requested and observed != requested)}


def model_versions(run, models=None):
    """Read each completed model's execution source before run-level fallbacks."""
    selected = tuple(models) if models is not None else run_models(run)
    run_version = native_version(run)
    result = {}
    for model in selected:
        if model not in MODEL_OUTPUTS:
            raise ValueError("Choose an original native model.")
        stage = (run.get("stages") or {}).get(model) or {}
        stage_version = _text((stage.get("runtime") or {}).get("version")) if stage.get("completed_at") else None
        effective = stage_version or run_version["comparison_version"]
        result[model] = {
            "model": model, "comparison_version": effective,
            "basis": "completed_stage_runtime" if stage_version else
                     "observed_run_fallback" if run_version["observed"] else run_version["basis"],
            "observed_stage_version": stage_version,
            "observed_run_version": run_version["observed"],
            "requested_version": run_version["requested"],
            "differs_from_requested": bool(effective and run_version["requested"] and
                                            effective != run_version["requested"]),
            "stage_completed_at": stage.get("completed_at"),
            "reused_from": deepcopy(stage.get("reused_from")),
        }
    return result


def models_for_outputs(outputs):
    selected = set(outputs)
    return tuple(model for model, names in MODEL_OUTPUTS.items() if selected.intersection(names))


def comparison_versions(runs, models):
    """Resolve a per-common-model cohort without flattening mixed executed stages."""
    if not runs:
        raise ValueError("Choose retained native runs for this comparison.")
    selected = tuple(models)
    if not selected:
        raise ValueError("Choose at least one common native model.")
    by_run = {run["id"]: model_versions(run, selected) for run in runs}
    baseline = by_run[runs[0]["id"]]
    for run_id, versions in by_run.items():
        for model in selected:
            value = versions[model]["comparison_version"]
            if not value:
                raise ValueError("Native " + model.upper() + " run " + run_id +
                                 " has no completed-stage, observed-run or retained requested version.")
            if value != baseline[model]["comparison_version"]:
                raise ValueError("Compared " + model.upper() + " execution versions differ: " +
                                 str(baseline[model]["comparison_version"]) + " versus " + str(value) +
                                 " for run " + run_id + ".")
    return {"policy": POLICY, "models": list(selected),
            "versions": {model: baseline[model]["comparison_version"] for model in selected},
            "runs": by_run}


def version_label(info):
    """Describe a retained version without turning a fallback into execution evidence."""
    info = info or {}
    version = _text(info.get("comparison_version"))
    if not version:
        return "InVEST version unavailable"
    basis = info.get("basis")
    descriptions = {
        "completed_stage_runtime": "completed stage runtime",
        "observed_run_fallback": "observed run runtime; stage version unavailable",
        "observed_runtime": "observed run runtime",
        "requested_legacy": "requested legacy version; execution version unavailable",
    }
    description = descriptions.get(basis, "retained version; source basis unavailable")
    requested = _text(info.get("requested_version")) or _text(info.get("requested"))
    if requested and requested != version:
        description += "; requested " + requested
    return "InVEST " + version + " (" + description + ")"


def guide_url(model, info):
    """Return the model guide for the retained comparison version, when available."""
    if model not in MODEL_OUTPUTS:
        raise ValueError("Choose an original native model.")
    version = _text((info or {}).get("comparison_version"))
    if not version:
        return None
    return ("https://storage.googleapis.com/releases.naturalcapitalproject.org/invest/" +
            quote(version, safe="") + "/userguide/en/" + model + ".html")


def run_label(run):
    """Keep each selected model's version and source basis visible in one label."""
    return "; ".join(model.upper() + ": " + version_label(info)
                     for model, info in model_versions(run).items())


def run_comparison_identity(runs):
    """Use the producing runtimes and common output scope of completed runs."""
    from .model_selection import common_comparison_outputs
    if len(runs) < 2 or len({run["id"] for run in runs}) != len(runs):
        raise ValueError("Select a baseline and distinct original alternative runs")
    if any(run.get("state") != "complete" for run in runs):
        raise ValueError("Finish the selected original native comparison runs")
    if any(run["selection"]["grid_id"] != runs[0]["selection"]["grid_id"] for run in runs[1:]):
        raise ValueError("Run comparison requires the same retained reporting/model grid")
    outputs = common_comparison_outputs(runs)
    versions = comparison_versions(runs, models_for_outputs(outputs))
    return {"runs": [run["id"] for run in runs], "direction": "alternative minus baseline",
            "native_version_provenance": versions}


def validate_run_comparison(workspace, comparison, *, expected_id=None):
    """Validate current and original legacy comparison identities without rerunning models."""
    from .common import digest, identifier
    from .model_selection import common_comparison_outputs
    if "source_refresh_context" in comparison:
        from .source_refresh_comparison import validate
        return validate(workspace, comparison, expected_id=expected_id)
    if (comparison.get("schema") != "upstate.run-comparison/v1"
            or comparison.get("direction") != "alternative minus baseline"):
        raise ValueError("Select the retained alternative-minus-baseline comparison")
    key = identifier(comparison.get("id"))
    if expected_id is not None and key != identifier(expected_id):
        raise ValueError("The original comparison identity differs")
    ids = [identifier(comparison.get("baseline_run_id"))] + [
        identifier(item.get("run_id")) for item in comparison.get("alternatives", [])]
    runs = [workspace.inspect_run(run_id) for run_id in ids]
    identity = run_comparison_identity(runs)
    outputs = list(common_comparison_outputs(runs))
    if "native_version_provenance" in comparison:
        if (comparison["native_version_provenance"] != identity["native_version_provenance"]
                or comparison.get("common_artifacts") != outputs):
            raise ValueError("The retained comparison's native version or output scope changed")
    else:
        # Legacy records retain their exact original IDs; their producing models
        # must still be compatible through the same current runtime resolver.
        identity.pop("native_version_provenance")
        if "common_artifacts" in comparison and comparison["common_artifacts"] != outputs:
            raise ValueError("The original comparison output scope changed")
    if digest(identity) != key:
        raise ValueError("The original native comparison changed its run cohort")
    for alternative, run in zip(comparison["alternatives"], runs[1:]):
        if (alternative.get("selection") != run["selection"]
                or set(alternative.get("artifacts", {})) != set(outputs)):
            raise ValueError("The native comparison differs from its original run or output selection")
    return comparison

